struct Container<'a> {
    value: &'a i32,
}

impl<'a> Clone for Container<'a> {
    fn clone(&self) -> Self {
        Container { value: self.value }
    }
}

fn main() {
    let x = 10;
    let container = Container { value: &x };

    // Clone is only valid if the reference is valid at runtime
    let cloned = container.clone();

    // Assert that the cloned value is correct
    assert_eq!(*cloned.value, 10);

    // Assert that the original reference is still valid
    assert_eq!(*container.value, 10);

    println!("PASS");
}
